// The test ROM is generated by scripts/make-test-rom.mjs. These checks keep the committed file equal to the script's
// output and run its code on a small 6502 model (only the instructions it uses), with the pads stubbed.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = resolve(__dirname, '../../../../..');
const romPath = resolve(root, 'e2e/fixtures/emu/sideroom-test.nes');

async function gen() {
  return (await import(pathToFileURL(resolve(root, 'scripts/make-test-rom.mjs')).href)) as {
    buildRom(): Uint8Array;
    COLOR_IDLE: number;
    COLOR_P1_A: number;
    COLOR_P2_A: number;
  };
}

/** Run until the program writes the palette entry; return the colour. A tiny model: vblank is always set. */
function colourFor(rom: Uint8Array, p1A: boolean, p2A: boolean): number {
  const prg = rom.subarray(16, 16 + 16384);
  const mem = new Uint8Array(0x800);
  let pc = prg[0x3ffc]! | (prg[0x3ffd]! << 8);
  let a = 0;
  let x = 0;
  let z = false;
  let n = false;
  const ppuAddr: number[] = [];
  const rd = (addr: number): number => {
    if (addr === 0x2002) return 0x80;
    if (addr === 0x4016) return p1A ? 1 : 0;
    if (addr === 0x4017) return p2A ? 1 : 0;
    if (addr >= 0xc000) return prg[addr - 0xc000]!;
    if (addr < 0x800) return mem[addr]!;
    return 0;
  };
  for (let steps = 0; steps < 5000; steps++) {
    const op = rd(pc);
    const b1 = rd(pc + 1);
    const abs = b1 | (rd(pc + 2) << 8);
    const flags = (v: number) => {
      z = v === 0;
      n = (v & 0x80) !== 0;
    };
    switch (op) {
      case 0x78:
      case 0xd8:
      case 0x9a:
        pc += 1;
        break;
      case 0xe8:
        x = (x + 1) & 0xff;
        flags(x);
        pc += 1;
        break;
      case 0xa2:
        x = b1;
        flags(x);
        pc += 2;
        break;
      case 0xa9:
        a = b1;
        flags(a);
        pc += 2;
        break;
      case 0x29:
        a &= b1;
        flags(a);
        pc += 2;
        break;
      case 0x85:
        mem[b1] = a;
        pc += 2;
        break;
      case 0xa5:
        a = mem[b1]!;
        flags(a);
        pc += 2;
        break;
      case 0xa6:
        x = mem[b1]!;
        flags(x);
        pc += 2;
        break;
      case 0xad:
        a = rd(abs);
        flags(a);
        pc += 3;
        break;
      case 0x2c:
        n = (rd(abs) & 0x80) !== 0;
        pc += 3;
        break;
      case 0x10:
        pc += 2 + (n ? 0 : (b1 << 24) >> 24);
        break;
      case 0xf0:
        pc += 2 + (z ? (b1 << 24) >> 24 : 0);
        break;
      case 0x4c:
        pc = abs;
        break;
      case 0x8d:
      case 0x8e:
        if (abs === 0x2006) ppuAddr.push(op === 0x8d ? a : x);
        if (abs === 0x2007 && ppuAddr.length >= 2 && ppuAddr[0] === 0x3f && ppuAddr[1] === 0x00)
          return a;
        pc += 3;
        break;
      default:
        throw new Error(`unmodelled opcode ${op.toString(16)} at ${pc.toString(16)}`);
    }
  }
  throw new Error('the program never painted');
}

describe('the generated test ROM', () => {
  it('is the committed file, byte for byte', async () => {
    const { buildRom } = await gen();
    expect(Buffer.compare(Buffer.from(buildRom()), readFileSync(romPath))).toBe(0);
  });
  it('is a valid iNES NROM-128 image with its vectors at the reset code', async () => {
    const rom = readFileSync(romPath);
    expect(rom.subarray(0, 4).toString('latin1')).toBe('NES\x1a');
    expect([rom[4], rom[5]]).toEqual([1, 1]);
    expect(rom.length).toBe(16 + 16384 + 8192);
    expect(rom[16 + 0x3ffc]).toBe(0x00);
    expect(rom[16 + 0x3ffd]).toBe(0xc0);
  });
  it('reads both controllers', () => {
    const prg = readFileSync(romPath).subarray(16, 16 + 16384);
    const has = (...seq: number[]) => prg.some((_, i) => seq.every((v, k) => prg[i + k] === v));
    expect(has(0xad, 0x16, 0x40)).toBe(true); // LDA $4016
    expect(has(0xad, 0x17, 0x40)).toBe(true); // LDA $4017
  });
  it('is red idle, blue while pad 1 holds A and green while pad 2 holds A', async () => {
    const { buildRom, COLOR_IDLE, COLOR_P1_A, COLOR_P2_A } = await gen();
    const rom = buildRom();
    expect(colourFor(rom, false, false)).toBe(COLOR_IDLE);
    expect(colourFor(rom, true, false)).toBe(COLOR_P1_A);
    expect(colourFor(rom, false, true)).toBe(COLOR_P2_A);
    expect(colourFor(rom, true, true)).toBe(COLOR_P2_A);
    expect(new Set([COLOR_IDLE, COLOR_P1_A, COLOR_P2_A]).size).toBe(3);
  });
});
